    host=document.createElement('div');host.id='seriesPage';host.className='series-page';
    host.setAttribute('role','dialog');host.setAttribute('aria-label','Tất cả bộ Chuyển thể Series');
    document.body.appendChild(host);
    host.addEventListener('click',function(e){
      var el=e.target.closest?e.target.closest('[data-act]'):null;
      if(!el)return;
      var a=el.dataset.act;
      if(a!=='series-close'&&a!=='series-save'&&a!=='series-all'&&a!=='series-none')return;
      e.stopPropagation();
      if(a==='series-close'){closeSeriesPage();return;}
