function sanitizeEditorHtml(input){
  var src=String(input==null?'':input)
    .replace(/<\s*(script|iframe|object|embed|link|meta|base|style|form|svg|math|template)\b[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi,'')
    .replace(/<\s*(script|iframe|object|embed|link|meta|base|style|form|svg|math|template)\b[^>]*\/?>/gi,'')
    .replace(/\son[a-z0-9_-]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi,'')
    .replace(/\s(?:srcdoc|formaction)\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi,'')
    .replace(/(\s(?:href|src|xlink:href)\s*=\s*)(["']?)\s*(?:javascript|data|blob):[^"'<>\s]*\2/gi,'');
  var box=document.createElement('div');
  box.innerHTML=src;
  var allowed={P:1,BR:1,B:1,STRONG:1,I:1,EM:1,U:1,H1:1,H2:1,H3:1,H4:1,BLOCKQUOTE:1,UL:1,OL:1,LI:1,A:1,IMG:1,DIV:1,SPAN:1,HR:1};
  Array.prototype.slice.call(box.querySelectorAll('*')).forEach(function(el){
    var tag=el.tagName.toUpperCase();
    Array.prototype.slice.call(el.attributes).forEach(function(a){
      var nm=a.name.toLowerCase(),v=String(a.value||'').trim();
      if(/^on/i.test(nm)||nm==='srcdoc'||nm==='formaction'){el.removeAttribute(a.name);return;}
      if((nm==='href'||nm==='src'||nm==='xlink:href')&&/^\s*(?:javascript|data|blob):/i.test(v)){el.removeAttribute(a.name);return;}
      if(nm==='style'&&/(?:url\s*\(|expression\s*\()/i.test(v))el.removeAttribute(a.name);
    });
    if(!allowed[tag]){
      var par=el.parentNode;if(!par)return;
      while(el.firstChild)par.insertBefore(el.firstChild,el);
      par.removeChild(el);return;
    }
    Array.prototype.slice.call(el.classList).forEach(function(c){if(c!=='ch-sep')el.classList.remove(c);});
    if(!el.getAttribute('class'))el.removeAttribute('class');
  });
  return box.innerHTML;
}
